401	    /// Queries the content tree for the first element that match the given
402	    /// selector.
403	    ///
404	    /// This is a *naive hack* because contextual content and elements produced
405	    /// in `show` rules will not be included in the results. It's used should
406	    /// be avoided.
407	    pub fn query_first_naive(&self, selector: &Selector) -> Option<Content> {
408	        self.traverse(&mut |element| -> ControlFlow<Content> {
409	            if selector.matches(&element, None) {
410	                ControlFlow::Break(element)
411	            } else {
412	                ControlFlow::Continue(())
413	            }
414	        })
415	        .break_value()
416	    }
417	
418	    /// Extracts the plain text of this content.
419	    pub fn plain_text(&self) -> EcoString {
420	        let mut text = EcoString::new();
421	        let _ = self.traverse(&mut |element| -> ControlFlow<()> {
422	            if let Some(textable) = element.with::<dyn PlainText>() {
423	                textable.plain_text(&mut text);
424	            }
425	            ControlFlow::Continue(())
426	        });
427	        text
428	    }
429	
430	    /// Traverse this content.
431	    pub fn traverse<F, B>(&self, f: &mut F) -> ControlFlow<B>
432	    where
433	        F: FnMut(Content) -> ControlFlow<B>,
434	    {
435	        /// Walks a given value to find any content that matches the selector.
436	        ///
437	        /// Returns early if the function gives `ControlFlow::Break`.
438	        fn walk_value<F, B>(value: Value, f: &mut F) -> ControlFlow<B>
439	        where
440	            F: FnMut(Content) -> ControlFlow<B>,
441	        {
442	            match value {
443	                Value::Content(content) => content.traverse(f),
444	                Value::Array(array) => {
445	                    for value in array {
446	                        walk_value(value, f)?;
447	                    }
448	                    ControlFlow::Continue(())
449	                }
450	                _ => ControlFlow::Continue(()),
451	            }
452	        }
453	
454	        // Call f on the element itself before recursively iterating its fields.
455	        f(self.clone())?;
456	        for (_, value) in self.fields() {
457	            walk_value(value, f)?;
458	        }
459	        ControlFlow::Continue(())
460	    }
461	}
