557	    /// Access the specified field on the content. Returns the default value if
558	    /// the field does not exist or fails with an error if no default value was
559	    /// specified.
560	    #[func(since = "forever")]
561	    pub fn at(
562	        &self,
563	        /// The field to access.
564	        field: Str,
565	        /// A default value to return if the field does not exist.
566	        #[named]
567	        default: Option<Value>,
568	    ) -> StrResult<Value> {
569	        self.get_by_name(&field)
570	            .or_else(|e| default.ok_or(e))
571	            .map_err(|e| e.message_no_default(self, &field))
572	    }
573	
574	    /// Returns the fields of this content.
575	    ///
576	    /// ```example
577	    /// #rect(
578	    ///   width: 10cm,
579	    ///   height: 10cm,
580	    /// ).fields()
581	    /// ```
582	    #[func(since = "0.5.0")]
583	    pub fn fields(&self) -> Dict {
584	        let mut dict = Dict::new();
585	        for field in self.0.handle().fields() {
586	            if let Some(value) = field.get() {
587	                dict.insert(field.name.into(), value);
588	            }
589	        }
590	        if let Some(label) = self.label() {
591	            dict.insert("label".into(), label.into_value());
592	        }
593	        dict
594	    }
