596	    /// The location of the content. This is only available on content returned
597	    /// by @query[query] or provided by a
598	    /// @reference:styling:show-rules[show rule], for other content it will be
599	    /// `{none}`. The resulting location can be used with @counter[counters],
600	    /// @state[state] and @query[queries].
601	    #[func(since = "forever")]
602	    pub fn location(&self) -> Option<Location> {
603	        self.0.meta().location
604	    }
605	}
