544	trait Bounds: Debug + Repr + Any + Sync + Send + 'static {
545	    fn dyn_eq(&self, other: &Dynamic) -> bool;
546	    fn dyn_ty(&self) -> Type;
547	    fn dyn_hash(&self, state: &mut dyn Hasher);
